import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import {
  Brain,
  Target,
  Trophy,
  Zap,
  Shield,
  Star,
  Crown,
  Rocket,
  Flame
} from 'lucide-react';

const AIInsights: React.FC = () => {
  const { tasks, assignments, studySessions } = useApp();
  const [insights, setInsights] = useState<any[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    const generateAIInsights = async () => {
      setIsAnalyzing(true);

      // Simulate AI processing delay
      await new Promise(resolve => setTimeout(resolve, 2000));

      const aiInsights = [];

      // Analyze work patterns
      const today = new Date();
      const studyHoursToday = studySessions
        .filter(s => new Date(s.completedAt).toDateString() === today.toDateString())
        .reduce((total, s) => total + s.duration, 0) / 60;

      if (studyHoursToday > 6) {
        aiInsights.push({
          id: 'study-marathon',
          type: 'achievement',
          title: '🔥 Study Marathon Achieved!',
          description: `You've studied ${studyHoursToday.toFixed(1)} hours today! That's incredible dedication.`,
          icon: <Rocket className="w-6 h-6 text-orange-500" />,
          confidence: 95,
          actionable: true,
          actions: [
            { text: 'Share achievement', primary: true },
            { text: 'Take a break', primary: false }
          ]
        });
      }

      // Analyze task completion patterns
      const completedTasks = tasks.filter(t => t.status === 'completed').length;
      const pendingTasks = tasks.filter(t => t.status === 'pending').length;
      const completionRate = (completedTasks / (completedTasks + pendingTasks)) * 100;

      if (completionRate > 85) {
        aiInsights.push({
          id: 'productivity-master',
          type: 'insight',
          title: '👑 Productivity Master',
          description: `Your task completion rate is ${completionRate.toFixed(1)}% - you're in the top 5% of users!`,
          icon: <Trophy className="w-6 h-6 text-yellow-500" />,
          confidence: 92,
          actionable: true,
          actions: [
            { text: 'View detailed analytics', primary: true },
            { text: 'Set higher goals', primary: false }
          ]
        });
      }

      // Analyze assignment performance
      const completedAssignments = assignments.filter(a => a.status === 'completed' && a.grade !== undefined);
      const averageGrade = completedAssignments.length > 0
        ? completedAssignments.reduce((sum, a) => sum + (a.grade || 0), 0) / completedAssignments.length
        : 0;

      if (averageGrade >= 90) {
        aiInsights.push({
          id: 'academic-excellence',
          type: 'achievement',
          title: '🎓 Academic Excellence',
          description: `Your average grade is ${averageGrade.toFixed(1)}% - outstanding academic performance!`,
          icon: <Crown className="w-6 h-6 text-purple-500" />,
          confidence: 98,
          actionable: true,
          actions: [
            { text: 'View grade analytics', primary: true },
            { text: 'Set higher targets', primary: false }
          ]
        });
      }

      // Analyze consistency patterns
      const studyDays = Array.from(new Set(studySessions.map(s => new Date(s.completedAt).toDateString())));
      const last7Days: string[] = [];
      for (let i = 6; i >= 0; i--) {
        const date = new Date(today);
        date.setDate(date.getDate() - i);
        last7Days.push(date.toDateString());
      }

      const consistencyScore = (studyDays.filter(day => last7Days.includes(day)).length / 7) * 100;

      if (consistencyScore >= 85) {
        aiInsights.push({
          id: 'consistency-legend',
          type: 'insight',
          title: '🌟 Consistency Legend',
          description: `You've studied ${studyDays.filter(day => last7Days.includes(day)).length} out of the last 7 days! Amazing consistency!`,
          icon: <Star className="w-6 h-6 text-green-500" />,
          confidence: 94,
          actionable: false,
          actions: []
        });
      }

      // Predictive insights
      const upcomingDeadlines = assignments
        .filter(a => a.status !== 'completed')
        .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime())
        .slice(0, 3);

      if (upcomingDeadlines.length >= 2) {
        const daysUntilFirst = Math.ceil((new Date(upcomingDeadlines[0].dueDate).getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

        aiInsights.push({
          id: 'deadline-pressure',
          type: 'warning',
          title: '⚡ Upcoming Deadline Pressure',
          description: `You have ${upcomingDeadlines.length} assignments due soon. The first is due in ${daysUntilFirst} days.`,
          icon: <Target className="w-6 h-6 text-red-500" />,
          confidence: 89,
          actionable: true,
          priority: 'high',
          actions: [
            { text: 'View assignments', primary: true },
            { text: 'Create study plan', primary: false }
          ]
        });
      }

      // Study optimization insights
      const avgSessionLength = studySessions.length > 0
        ? studySessions.reduce((sum, s) => sum + s.duration, 0) / studySessions.length
        : 0;

      if (avgSessionLength < 20) {
        aiInsights.push({
          id: 'study-optimization',
          type: 'recommendation',
          title: '💡 Study Optimization',
          description: `Your average study session is ${avgSessionLength.toFixed(1)} minutes. Consider increasing to 25-45 minutes for better retention.`,
          icon: <Brain className="w-6 h-6 text-blue-500" />,
          confidence: 85,
          actionable: true,
          actions: [
            { text: 'Try Pomodoro timer', primary: true },
            { text: 'Read study tips', primary: false }
          ]
        });
      }

      // Productivity predictions
      const weeklyProductivity = [];
      const last4Weeks = [];

      for (let i = 3; i >= 0; i--) {
        const weekStart = new Date(today);
        weekStart.setDate(weekStart.getDate() - (i * 7));
        weekStart.setDate(weekStart.getDate() - weekStart.getDay());

        const weekEnd = new Date(weekStart);
        weekEnd.setDate(weekEnd.getDate() + 6);

        const weekTasks = tasks.filter(t => {
          const taskDate = new Date(t.createdAt);
          return taskDate >= weekStart && taskDate <= weekEnd;
        });

        const weekCompleted = weekTasks.filter(t => t.status === 'completed').length;
        last4Weeks.push(weekCompleted);
      }

      const avgWeeklyCompletion = last4Weeks.reduce((sum, week) => sum + week, 0) / last4Weeks.length;
      const recentWeeklyCompletion = last4Weeks[last4Weeks.length - 1];

      if (recentWeeklyCompletion > avgWeeklyCompletion * 1.2) {
        aiInsights.push({
          id: 'momentum-builder',
          type: 'achievement',
          title: '🚀 Momentum Builder',
          description: `Your productivity increased by ${((recentWeeklyCompletion / avgWeeklyCompletion - 1) * 100).toFixed(1)}% this week! Keep the momentum going!`,
          icon: <Zap className="w-6 h-6 text-green-500" />,
          confidence: 88,
          actionable: true,
          actions: [
            { text: 'Set challenging goals', primary: true },
            { text: 'Share progress', primary: false }
          ]
        });
      }

      // Personalized recommendations
      const personalInsights = [];

      if (tasks.length > 20) {
        const overdueTasks = tasks.filter(t =>
          t.status === 'pending' && new Date(t.dueDate) < today
        ).length;

        if (overdueTasks > 0) {
          personalInsights.push({
            id: 'task-management',
            type: 'recommendation',
            title: '📋 Task Management',
            description: `You have ${overdueTasks} overdue tasks. Consider breaking down large tasks and setting more frequent reminders.`,
            icon: <Target className="w-6 h-6 text-orange-500" />,
            confidence: 91,
            actionable: true,
            actions: [
              { text: 'Review overdue tasks', primary: true },
              { text: 'Set smart reminders', primary: false }
            ]
          });
        }
      }

      // Study time recommendations
      const totalStudyTime = studySessions.reduce((total, s) => total + s.duration, 0);
      const avgDailyStudy = totalStudyTime / Math.max(studyDays.length, 7);

      if (avgDailyStudy < 60) { // Less than 1 hour per day
        personalInsights.push({
          id: 'study-habits',
          type: 'recommendation',
          title: '📚 Study Habits',
          description: `Your current average is ${Math.floor(avgDailyStudy)} minutes per day. Consistent daily sessions of 60+ minutes can significantly improve retention and grades.`,
          icon: <Brain className="w-6 h-6 text-purple-500" />,
          confidence: 87,
          actionable: true,
          actions: [
            { text: 'Schedule daily sessions', primary: true },
            { text: 'Set study goals', primary: false }
          ]
        });
      }

      setInsights([...aiInsights, ...personalInsights]);
      setIsAnalyzing(false);
    };

    generateAIInsights();
  }, [tasks, assignments, studySessions]);

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 95) return 'text-green-600';
    if (confidence >= 90) return 'text-blue-600';
    if (confidence >= 85) return 'text-yellow-600';
    return 'text-orange-600';
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'achievement': return <Trophy className="w-5 h-5 text-yellow-500" />;
      case 'insight': return <Brain className="w-5 h-5 text-blue-500" />;
      case 'warning': return <Target className="w-5 h-5 text-red-500" />;
      case 'recommendation': return <Zap className="w-5 h-5 text-purple-500" />;
      default: return <Star className="w-5 h-5 text-gray-500" />;
    }
  };

  const getPriorityBadge = (priority: string) => {
    switch (priority) {
      case 'high': return 'bg-red-100 text-red-800 px-2 py-1 rounded-full text-xs font-semibold';
      case 'medium': return 'bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full text-xs font-semibold';
      default: return 'bg-blue-100 text-blue-800 px-2 py-1 rounded-full text-xs font-semibold';
    }
  };

  if (isAnalyzing) {
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
        <div className="card p-8 max-w-md">
          <div className="text-center">
            <div className="relative inline-flex items-center justify-center w-16 h-16 mb-4">
              <Brain className="w-8 h-8 text-blue-600 animate-pulse" />
              <div className="absolute inset-0 border-2 border-blue-200 rounded-full animate-spin"></div>
            </div>
            <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              🤖 AI Analysis
            </h3>
            <p className="text-gray-600 dark:text-gray-300 mb-4">
              Analyzing your productivity patterns, study habits, and academic performance...
            </p>
            <div className="space-y-2">
              <div className="h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-blue-600 rounded-full animate-pulse" style={{ width: '75%' }}></div>
              </div>
              <div className="h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-purple-600 rounded-full animate-pulse" style={{ width: '60%' }}></div>
              </div>
              <div className="h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-green-600 rounded-full animate-pulse" style={{ width: '90%' }}></div>
              </div>
            </div>
            <p className="text-sm text-blue-600 dark:text-blue-400">
              Generating personalized insights... {Math.floor(Math.random() * 40 + 50)}%
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3 mb-6">
        <div className="relative">
          <Brain className="w-8 h-8 text-purple-600" />
          <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
        </div>
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            🤖 AI Insights & Recommendations
          </h1>
          <p className="text-gray-600 dark:text-gray-300">
            Personalized analysis powered by artificial intelligence
          </p>
        </div>
        <div className="flex items-center gap-2 px-3 py-2 bg-green-100 dark:bg-green-900/30 rounded-full">
          <Zap className="w-4 h-4 text-green-600" />
          <span className="text-sm font-semibold text-green-800 dark:text-green-300">AI Active</span>
        </div>
      </div>

      {/* Stats Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        <div className="card p-6 text-center">
          <Trophy className="w-8 h-8 text-yellow-500 mx-auto mb-3" />
          <div className="text-3xl font-bold text-gray-900 dark:text-white">{insights.length}</div>
          <p className="text-sm text-gray-600 dark:text-gray-300">Total Insights</p>
        </div>
        <div className="card p-6 text-center">
          <Brain className="w-8 h-8 text-blue-500 mx-auto mb-3" />
          <div className="text-3xl font-bold text-gray-900 dark:text-white">
            {insights.filter(i => i.type === 'achievement').length}
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-300">Achievements</p>
        </div>
        <div className="card p-6 text-center">
          <Zap className="w-8 h-8 text-purple-500 mx-auto mb-3" />
          <div className="text-3xl font-bold text-gray-900 dark:text-white">
            {Math.round(insights.reduce((sum, i) => sum + i.confidence, 0) / insights.length)}%
          </div>
          <p className="text-sm text-gray-600 dark:text-gray-300">AI Confidence</p>
        </div>
      </div>

      {/* Insights Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {insights.map((insight, index) => (
          <div
            key={insight.id}
            className={`card p-6 hover-lift transition-all duration-300 ${insight.type === 'achievement' ? 'border-yellow-200 dark:border-yellow-800' :
              insight.type === 'warning' ? 'border-red-200 dark:border-red-800' :
                insight.type === 'recommendation' ? 'border-purple-200 dark:border-purple-800' :
                  'border-blue-200 dark:border-blue-800'
              }`}
            style={{
              animationDelay: `${index * 0.1}s`
            }}
          >
            {/* Insight Header */}
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-gray-100 dark:bg-gray-800 rounded-lg">
                  {getTypeIcon(insight.type)}
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                    {insight.title}
                  </h3>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-xs px-2 py-1 bg-gray-200 dark:bg-gray-700 rounded-full">
                      {insight.type.charAt(0).toUpperCase() + insight.type.slice(1)}
                    </span>
                    <span className={`text-xs ${getConfidenceColor(insight.confidence)}`}>
                      {insight.confidence}% confidence
                    </span>
                  </div>
                </div>
              </div>
              {insight.priority === 'high' && (
                <span className="px-2 py-1 bg-red-100 text-red-800 rounded-full text-xs font-semibold">
                  High Priority
                </span>
              )}
            </div>

            {/* Insight Description */}
            <p className="text-gray-700 dark:text-gray-300 mb-6 text-sm leading-relaxed">
              {insight.description}
            </p>

            {/* Action Buttons */}
            {insight.actionable && (
              <div className="space-y-3">
                <div className="flex items-center gap-2 text-xs text-gray-600 dark:text-gray-400">
                  <Shield className="w-3 h-3" />
                  AI-Recommended Actions:
                </div>
                <div className="flex gap-2">
                  {insight.actions.map((action: { text: string; primary: boolean }, actionIndex: number) => (
                    <button
                      key={actionIndex}
                      className={`${action.primary
                        ? 'btn-primary'
                        : 'btn-secondary'
                        } ${action.primary ? 'flex-1' : ''}`}
                    >
                      {action.text}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* AI Status Bar */}
      <div className="card p-4 bg-gradient-to-r from-purple-50 to-blue-50 dark:from-purple-900/20 dark:to-blue-900/20">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Flame className="w-5 h-5 text-orange-500" />
            <div>
              <h4 className="font-semibold text-gray-900 dark:text-white">
                🤖 Neural Network Active
              </h4>
              <p className="text-sm text-gray-600 dark:text-gray-300">
                Deep learning model analyzing your patterns in real-time
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
            <span className="text-sm text-green-600 dark:text-green-400">Online</span>
          </div>
        </div>
      </div>

      {/* Footer */}
      <div className="text-center mt-8">
        <div className="inline-flex items-center gap-2 px-4 py-2 bg-blue-50 dark:bg-blue-900/30 rounded-full">
          <Star className="w-4 h-4 text-blue-600" />
          <span className="text-sm text-blue-800 dark:text-blue-300 font-medium">
            AI updates every 30 minutes
          </span>
        </div>
        <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
          Insights are personalized based on your unique patterns and behaviors
        </p>
      </div>
    </div>
  );
};

export default AIInsights;

import React, { useState, useEffect } from 'react';
import { Trophy, Target, Clock, Brain, Award, TrendingUp } from 'lucide-react';
import { useApp } from '../context/AppContext';

const AchievementSystem: React.FC = () => {
  const { tasks, assignments, studySessions } = useApp();
  const [achievements, setAchievements] = useState<any[]>([]);
  const [showCelebration, setShowCelebration] = useState(false);

  useEffect(() => {
    const checkAchievements = () => {
      const newAchievements = [];

      // Task achievements
      const completedTasks = tasks.filter(t => t.status === 'completed').length;
      if (completedTasks >= 1) {
        newAchievements.push({
          id: 'first-task',
          title: 'First Step',
          description: 'Complete your first task',
          icon: <Target className="w-6 h-6" />,
          color: 'bg-blue-500',
          unlocked: true
        });
      }
      if (completedTasks >= 10) {
        newAchievements.push({
          id: 'task-master',
          title: 'Task Master',
          description: 'Complete 10 tasks',
          icon: <Trophy className="w-6 h-6" />,
          color: 'bg-green-500',
          unlocked: true
        });
      }
      if (completedTasks >= 50) {
        newAchievements.push({
          id: 'task-champion',
          title: 'Task Champion',
          description: 'Complete 50 tasks',
          icon: <Award className="w-6 h-6" />,
          color: 'bg-purple-500',
          unlocked: true
        });
      }

      // Assignment achievements
      const completedAssignments = assignments.filter(a => a.status === 'completed').length;
      if (completedAssignments >= 1) {
        newAchievements.push({
          id: 'first-assignment',
          title: 'Assignment Complete',
          description: 'Complete your first assignment',
          icon: <Target className="w-6 h-6" />,
          color: 'bg-orange-500',
          unlocked: true
        });
      }

      // Study achievements
      const totalStudyTime = studySessions.reduce((total, session) => total + session.duration, 0);
      if (totalStudyTime >= 25) { // 25 minutes
        newAchievements.push({
          id: 'first-pomodoro',
          title: 'Pomodoro Pro',
          description: 'Complete your first Pomodoro session',
          icon: <Clock className="w-6 h-6" />,
          color: 'bg-red-500',
          unlocked: true
        });
      }
      if (totalStudyTime >= 150) { // 2.5 hours
        newAchievements.push({
          id: 'study-warrior',
          title: 'Study Warrior',
          description: 'Study for 2.5 hours total',
          icon: <Brain className="w-6 h-6" />,
          color: 'bg-indigo-500',
          unlocked: true
        });
      }
      if (totalStudyTime >= 600) { // 10 hours
        newAchievements.push({
          id: 'study-master',
          title: 'Study Master',
          description: 'Study for 10 hours total',
          icon: <Trophy className="w-6 h-6" />,
          color: 'bg-yellow-500',
          unlocked: true
        });
      }

      // Streak achievements
      const today = new Date().toDateString();
      const todayTasks = tasks.filter(t => 
        t.status === 'completed' && 
        new Date(t.createdAt).toDateString() === today
      ).length;

      if (todayTasks >= 5) {
        newAchievements.push({
          id: 'productive-day',
          title: 'Productive Day',
          description: 'Complete 5 tasks in one day',
          icon: <TrendingUp className="w-6 h-6" />,
          color: 'bg-teal-500',
          unlocked: true
        });
      }

      // Check for new achievements
      const existingIds = achievements.map(a => a.id);
      const newUnlocked = newAchievements.filter(a => 
        a.unlocked && !existingIds.includes(a.id)
      );

      if (newUnlocked.length > 0) {
        setShowCelebration(true);
        setTimeout(() => setShowCelebration(false), 3000);
      }

      setAchievements(newAchievements);
    };

    checkAchievements();
  }, [tasks, assignments, studySessions]);

  const allAchievements = [
    {
      id: 'first-task',
      title: 'First Step',
      description: 'Complete your first task',
      icon: <Target className="w-6 h-6" />,
      color: 'bg-blue-500',
      unlocked: false
    },
    {
      id: 'task-master',
      title: 'Task Master',
      description: 'Complete 10 tasks',
      icon: <Trophy className="w-6 h-6" />,
      color: 'bg-green-500',
      unlocked: false
    },
    {
      id: 'task-champion',
      title: 'Task Champion',
      description: 'Complete 50 tasks',
      icon: <Award className="w-6 h-6" />,
      color: 'bg-purple-500',
      unlocked: false
    },
    {
      id: 'first-assignment',
      title: 'Assignment Complete',
      description: 'Complete your first assignment',
      icon: <Target className="w-6 h-6" />,
      color: 'bg-orange-500',
      unlocked: false
    },
    {
      id: 'first-pomodoro',
      title: 'Pomodoro Pro',
      description: 'Complete your first Pomodoro session',
      icon: <Clock className="w-6 h-6" />,
      color: 'bg-red-500',
      unlocked: false
    },
    {
      id: 'study-warrior',
      title: 'Study Warrior',
      description: 'Study for 2.5 hours total',
      icon: <Brain className="w-6 h-6" />,
      color: 'bg-indigo-500',
      unlocked: false
    },
    {
      id: 'study-master',
      title: 'Study Master',
      description: 'Study for 10 hours total',
      icon: <Trophy className="w-6 h-6" />,
      color: 'bg-yellow-500',
      unlocked: false
    },
    {
      id: 'productive-day',
      title: 'Productive Day',
      description: 'Complete 5 tasks in one day',
      icon: <TrendingUp className="w-6 h-6" />,
      color: 'bg-teal-500',
      unlocked: false
    }
  ];

  const unlockedAchievements = allAchievements.filter(a => 
    achievements.find(ua => ua.id === a.id)?.unlocked
  );

  const lockedAchievements = allAchievements.filter(a => 
    !achievements.find(ua => ua.id === a.id)?.unlocked
  );

  return (
    <>
      {/* Celebration Modal */}
      {showCelebration && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="card p-8 text-center max-w-md slide-up">
            <Trophy className="w-16 h-16 text-yellow-500 mx-auto mb-4" />
            <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
              Achievement Unlocked! 🎉
            </h2>
            <p className="text-gray-600 dark:text-gray-300">
              Keep up the great work!
            </p>
          </div>
        </div>
      )}

      {/* Achievement Display */}
      <div className="space-y-6">
        {/* Stats */}
        <div className="card p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Achievements
            </h3>
            <div className="flex items-center gap-2">
              <Trophy className="w-5 h-5 text-yellow-500" />
              <span className="text-sm font-medium text-gray-900 dark:text-white">
                {unlockedAchievements.length}/{allAchievements.length}
              </span>
            </div>
          </div>

          <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
            <div 
              className="bg-gradient-to-r from-yellow-400 to-yellow-600 h-2 rounded-full transition-all duration-500"
              style={{ width: `${(unlockedAchievements.length / allAchievements.length) * 100}%` }}
            />
          </div>
        </div>

        {/* Unlocked Achievements */}
        {unlockedAchievements.length > 0 && (
          <div className="card p-6">
            <h4 className="text-md font-semibold text-gray-900 dark:text-white mb-4">
              Unlocked
            </h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {unlockedAchievements.map(achievement => (
                <div
                  key={achievement.id}
                  className="flex items-center gap-3 p-3 bg-gradient-to-r from-gray-50 to-gray-100 dark:from-gray-800 dark:to-gray-700 rounded-lg border border-gray-200 dark:border-gray-600"
                >
                  <div className={`p-2 rounded-lg ${achievement.color} text-white`}>
                    {achievement.icon}
                  </div>
                  <div className="flex-1">
                    <p className="font-medium text-gray-900 dark:text-white">
                      {achievement.title}
                    </p>
                    <p className="text-xs text-gray-600 dark:text-gray-300">
                      {achievement.description}
                    </p>
                  </div>
                  <Trophy className="w-4 h-4 text-yellow-500" />
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Locked Achievements */}
        {lockedAchievements.length > 0 && (
          <div className="card p-6">
            <h4 className="text-md font-semibold text-gray-900 dark:text-white mb-4">
              Locked
            </h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {lockedAchievements.map(achievement => (
                <div
                  key={achievement.id}
                  className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-800 rounded-lg opacity-60"
                >
                  <div className="p-2 rounded-lg bg-gray-300 dark:bg-gray-600 text-gray-500">
                    {achievement.icon}
                  </div>
                  <div className="flex-1">
                    <p className="font-medium text-gray-500 dark:text-gray-400">
                      {achievement.title}
                    </p>
                    <p className="text-xs text-gray-400 dark:text-gray-500">
                      {achievement.description}
                    </p>
                  </div>
                  <div className="w-4 h-4 rounded-full border-2 border-gray-300 dark:border-gray-600" />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </>
  );
};

export default AchievementSystem;

import React, { useState, useEffect } from 'react';
import { Search, Clock, Calendar, Target, TrendingUp, X } from 'lucide-react';
import { useApp } from '../context/AppContext';

interface QuickSearchProps {
  onClose: () => void;
}

const QuickSearch: React.FC<QuickSearchProps> = ({ onClose }) => {
  const { tasks, assignments, classSchedule } = useApp();
  const [searchTerm, setSearchTerm] = useState('');
  const [results, setResults] = useState<any[]>([]);
  const [selectedIndex, setSelectedIndex] = useState(0);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
      }
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(prev => Math.min(prev + 1, results.length - 1));
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(prev => Math.max(prev - 1, 0));
      }
      if (e.key === 'Enter') {
        e.preventDefault();
        if (results[selectedIndex]) {
          window.location.href = results[selectedIndex].url;
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [results, selectedIndex, onClose]);

  useEffect(() => {
    if (!searchTerm) {
      setResults([]);
      return;
    }

    const searchLower = searchTerm.toLowerCase();
    const searchResults: Array<{
      id: string;
      type: string;
      title: string;
      description: string;
      priority?: string;
      dueDate?: string;
      status?: string;
      grade?: number;
      url: string;
      icon: React.ReactNode;
    }> = [];

    // Search tasks
    tasks.forEach(task => {
      if (task.title.toLowerCase().includes(searchLower) ||
        (task.description && task.description.toLowerCase().includes(searchLower))) {
        searchResults.push({
          id: task.id,
          type: 'task',
          title: task.title,
          description: task.description || '',
          priority: task.priority,
          dueDate: task.dueDate,
          status: task.status,
          url: '/tasks',
          icon: <Target className="w-4 h-4" />
        });
      }
    });

    // Search assignments
    assignments.forEach(assignment => {
      if (assignment.title.toLowerCase().includes(searchLower) ||
        assignment.subject.toLowerCase().includes(searchLower) ||
        (assignment.description && assignment.description.toLowerCase().includes(searchLower))) {
        searchResults.push({
          id: assignment.id,
          type: 'assignment',
          title: assignment.title,
          description: assignment.subject,
          priority: assignment.status,
          dueDate: assignment.dueDate,
          status: assignment.status,
          grade: assignment.grade,
          url: '/assignments',
          icon: <Calendar className="w-4 h-4" />
        });
      }
    });

    // Search classes
    classSchedule.forEach(cls => {
      if (cls.subject.toLowerCase().includes(searchLower) ||
        cls.room.toLowerCase().includes(searchLower)) {
        searchResults.push({
          id: cls.id,
          type: 'class',
          title: cls.subject,
          description: `${cls.startTime} - ${cls.endTime} • Room ${cls.room}`,
          priority: 'medium',
          url: '/schedule',
          icon: <Clock className="w-4 h-4" />
        });
      }
    });

    setResults(searchResults.slice(0, 10));
    setSelectedIndex(0);
  }, [searchTerm, tasks, assignments, classSchedule]);

  const getStatusColor = (status: string, type: string) => {
    if (type === 'task') {
      if (status === 'completed') return 'text-green-600';
      if (status === 'in-progress') return 'text-blue-600';
      return 'text-yellow-600';
    }
    return 'text-gray-600';
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const today = new Date();
    const diffTime = date.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Today';
    if (diffDays === 1) return 'Tomorrow';
    if (diffDays === -1) return 'Yesterday';
    if (diffDays > 0) return `In ${diffDays} days`;
    return `${Math.abs(diffDays)} days ago`;
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-start justify-center pt-20 z-50 p-4">
      <div className="card w-full max-w-2xl shadow-2xl slide-up">
        {/* Search Input */}
        <div className="p-4 border-b border-gray-200 dark:border-gray-700">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Search tasks, assignments, classes..."
              className="input pl-10 text-lg w-full"
              autoFocus
            />
            <button
              onClick={onClose}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
            Press <kbd className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded text-xs">↑</kbd>
            <kbd className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded text-xs">↓</kbd> to navigate •
            <kbd className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded text-xs">Enter</kbd> to select •
            <kbd className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded text-xs">Esc</kbd> to close
          </div>
        </div>

        {/* Search Results */}
        <div className="max-h-96 overflow-y-auto">
          {results.length === 0 ? (
            <div className="p-8 text-center">
              <Search className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-500 dark:text-gray-400">
                {searchTerm ? 'No results found' : 'Type to search...'}
              </p>
            </div>
          ) : (
            <div className="p-2">
              {results.map((result, index) => (
                <a
                  key={result.id}
                  href={result.url}
                  className={`block p-3 rounded-lg cursor-pointer transition-colors ${index === selectedIndex
                    ? 'bg-primary-100 dark:bg-primary-900/20 border-primary-200 dark:border-primary-800'
                    : 'hover:bg-gray-50 dark:hover:bg-gray-700 border-transparent'
                    } border`}
                  onClick={(e) => {
                    e.preventDefault();
                    window.location.href = result.url;
                  }}
                >
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-lg ${result.type === 'task' ? 'bg-blue-100 dark:bg-blue-900/30' :
                      result.type === 'assignment' ? 'bg-green-100 dark:bg-green-900/30' :
                        'bg-purple-100 dark:bg-purple-900/30'
                      }`}>
                      {result.icon}
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-medium text-gray-900 dark:text-white">
                          {result.title}
                        </span>
                        <span className={`text-xs px-2 py-1 rounded-full border ${result.type === 'task' ? 'bg-blue-100 text-blue-800 border-blue-200' :
                          result.type === 'assignment' ? 'bg-green-100 text-green-800 border-green-200' :
                            'bg-purple-100 text-purple-800 border-purple-200'
                          }`}>
                          {result.type}
                        </span>
                        {result.priority && (
                          <span className={`text-xs font-medium ${getStatusColor(result.status, result.type)}`}>
                            {result.status}
                          </span>
                        )}
                      </div>

                      <div className="text-sm text-gray-600 dark:text-gray-300 truncate">
                        {result.description}
                      </div>

                      {result.dueDate && (
                        <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                          <Calendar className="w-3 h-3 inline mr-1" />
                          {formatDate(result.dueDate)}
                        </div>
                      )}

                      {result.grade && (
                        <div className="text-xs font-medium text-gray-500 dark:text-gray-400 mt-1">
                          Grade: {result.grade}%
                        </div>
                      )}
                    </div>
                  </div>
                </a>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuickSearch;
